{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Hyperoside, a quercetin 3-O-galactoside, was detected in rat brain after oral administration, demonstrating that flavonoid O-glycosides can achieve CNS access despite high polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a kaempferol 3-O-glucoside, transferred across the blood-brain barrier in rat tissue distribution studies, supporting O-glucosides of polyphenolic flavones as brain-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Isovitexin, an apigenin C-glucoside, reached 14.74 ng/mL in rat brain after intravenous dosing, showing that glycosylated flavones can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cyanidin-3-O-glucoside was detected in rat and human brain, providing direct evidence that anthocyanin O-glucosides cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Orientin, a luteolin C-glucoside, showed low brain levels after intravenous administration in rats due to high polarity; this is the closest negative but its C-glycosidic linkage makes it less transferable to the O-glucoside query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct in vivo brain detection of multiple flavonoid O-glycosides (hyperoside, astragalin, cyanidin-3-O-glucoside) outweighs the physicochemical prior and the single C-glucoside negative, supporting meaningful CNS access for luteolin-7-O-glucoside.",
  "evidence_gaps": [
    "No direct BBB measurement for luteolin-7-O-glucoside itself.",
    "Potential contribution of deglycosylation to luteolin aglycone is not resolved.",
    "Efflux transporter involvement and unbound brain concentrations are not quantified.",
    "Orientin negative suggests some luteolin glycosides may have limited access, so linkage-specific differences remain uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

